package local.skyfamily;
import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.util.*;import org.json.*;
public class GalleryActivity extends SnakeActivity {
 FramePlayer frame;final Handler idle=new Handler();boolean atHome=false,rememberAsked=false;String remembered="";
 @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=18&&!get("immich.vault").isEmpty())restore("",false);}
 @Override void page(String title){atHome=false;idle.removeCallbacksAndMessages(null);if(frame!=null){frame.close();frame=null;}getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);super.page(title);}
 @Override void home(){super.home();section("Photo frame");button("Start fullscreen Immich gallery",()->startGallery(false));button("Start fullscreen uploaded-photo gallery",()->startGallery(true));button("Gallery / screensaver settings",()->gallerySettings());atHome=true;armIdle();}
 void armIdle(){idle.removeCallbacksAndMessages(null);if(atHome&&prefs.getBoolean("gallery.idle",false))idle.postDelayed(()->{if(atHome){boolean local=prefs.getBoolean("gallery.local",false);if(local||!token.isEmpty())startGallery(local);else armIdle();}},prefs.getInt("gallery.idle.seconds",120)*1000L);}
 @Override public void onUserInteraction(){super.onUserInteraction();if(atHome)armIdle();}
 @Override void immich(){if(!token.isEmpty()){library();return;}if(get("immich.vault").isEmpty()){super.immich();text("This build can remember the session encrypted on this device. Your account password is not saved.");return;}page("Saved Immich sign-in");if(Build.VERSION.SDK_INT>=18){text("Restoring your encrypted device session...");restore("",true);}else{text("Android 4.2: enter the separate unlock passphrase you chose when saving this session. This is not your Immich password.");EditText pass=input("Unlock passphrase","");pass.setInputType(129);button("Unlock saved session",()->{String secret=pass.getText().toString();pass.setText("");restore(secret,true);});}button("Forget saved session and sign in again",()->forget());}
 void restore(String pass,boolean navigate){String blob=get("immich.vault");int stamp=revision;work(()->{JSONObject session=SessionVault.open(this,blob,pass);ui.post(()->{if(!token.isEmpty()||!get("immich.vault").equals(blob))return;if(navigate&&stamp!=revision)return;server=session.optString("server");token=session.optString("token");remembered=server+token;if(navigate)library();});});}
 void forget(){save("immich.vault","");token="";server="";remembered="";rememberAsked=false;assets=new JSONArray();albumFilter="";save("gallery.album","");immich();}
 void remember(String pass){if(token.isEmpty())return;final String s=server,t=token;if(remembered.equals(s+t))return;remembered=s+t;work(()->{try{String sealed=SessionVault.seal(this,s,t,pass);ui.post(()->{if(server.equals(s)&&token.equals(t)){save("immich.vault",sealed);toast("Immich session saved encrypted");}});}catch(Exception e){ui.post(()->{remembered="";toast("Could not save session: "+e.getMessage());});}});}
 @Override void library(){if(token.isEmpty()){immich();return;}page("Immich / your library");save("gallery.album",albumFilter);if(Build.VERSION.SDK_INT>=18)remember("");else if(get("immich.vault").isEmpty()&&!rememberAsked){rememberAsked=true;EditText secret=new EditText(this);secret.setInputType(129);secret.setHint("Separate unlock passphrase, at least 10 characters");new android.app.AlertDialog.Builder(this).setTitle("Remember Immich on Android 4.2").setMessage("Your session will be encrypted with this passphrase. Enter it once after restarting the app. The account password will not be saved.").setView(secret).setPositiveButton("Save session",(d,w)->remember(secret.getText().toString())).setNegativeButton("Not now",null).show();}button("Play this library / album fullscreen",()->startGallery(false));button("Choose album",()->albums());button("All photos and videos",()->{albumFilter="";assetPage=1;library();});button("Previous page",()->{assetPage=Math.max(1,assetPage-1);library();});button("Next page",()->{assetPage++;library();});button("Forget saved login / sign out locally",()->forget());text("Page "+assetPage+". Tap an item to open fullscreen.");final String s=server,t=token,album=albumFilter;final int current=assetPage,stamp=revision;work(()->{JSONObject query=new JSONObject().put("page",current).put("size",20);if(!album.isEmpty())query.put("albumIds",new JSONArray().put(album));JSONArray found=new JSONObject(new String(request(s+"/search/metadata","POST",query.toString(),t,6000000),"UTF-8")).getJSONObject("assets").getJSONArray("items");ui.post(()->{if(stamp!=revision)return;assets=found;for(int i=0;i<found.length();i++){JSONObject a=found.optJSONObject(i);if(a==null)continue;final int index=i;button(a.optString("originalFileName","Memory")+" / "+a.optString("type"),()->{position=index;showAsset(false);});}if(found.length()==0)text("No items on this page.");});});}
 @Override byte[] request(String address,String method,String json,String credential,int limit)throws Exception{URL url=new URL(address);if(!url.getProtocol().equals("https")&&!url.getProtocol().equals("http"))throw new IOException("HTTP(S) required");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setInstanceFollowRedirects(credential.isEmpty()&&method.equals("GET"));c.setRequestMethod(method);if(!credential.isEmpty())c.setRequestProperty("Authorization","Bearer "+credential);try{if(json!=null){byte[] bytes=json.getBytes("UTF-8");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}int code=c.getResponseCode();if(code<200||code>=300)throw new IOException(code==401?"Session expired or invalid. Forget saved login and reconnect.":"HTTP "+code+"; check server URL and compatibility");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Response exceeds limit");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 static class Slide {String address,credential,title;boolean video;File file;Slide(String a,String c,String name,boolean v){address=a;credential=c;title=name;video=v;}Slide(File f){file=f;title=f.getName();}}
 ArrayList<Slide> remoteSlides(JSONArray items,String s,String t){ArrayList<Slide> list=new ArrayList<>();for(int i=0;i<items.length();i++){JSONObject a=items.optJSONObject(i);if(a==null)continue;String id=a.optString("id");if(!id.matches("[A-Za-z0-9-]+"))continue;boolean video=a.optString("type").equals("VIDEO");list.add(new Slide(s+"/assets/"+id+(video?"/video/playback":"/thumbnail?size=preview"),t,a.optString("originalFileName","Memory"),video));}return list;}
 @Override void showAsset(boolean autoplay){ArrayList<Slide> list=remoteSlides(assets,server,token);if(list.isEmpty()){toast("No media to display");return;}openFrame(list,Math.min(position,list.size()-1),autoplay);}
 void startGallery(boolean local){prefs.edit().putBoolean("gallery.local",local).apply();if(!local&&token.isEmpty()){immich();return;}page("Preparing fullscreen gallery");text("Loading media list...");final int stamp=revision;final String s=server,t=token,album=get("gallery.album");work(()->{ArrayList<Slide> slides=new ArrayList<>();if(local){File[] files=new File(getFilesDir(),"uploads").listFiles((d,name)->name.endsWith(".image"));if(files!=null){Arrays.sort(files,(a,b)->Long.compare(a.lastModified(),b.lastModified()));for(File f:files)slides.add(new Slide(f));}}else{HashSet<String> seen=new HashSet<>();String cursor="";int page=1;for(int batch=0;batch<50;batch++){if(stamp!=revision)return;JSONObject q=new JSONObject().put("size",100);if(cursor.isEmpty())q.put("page",page);else q.put("cursor",cursor);if(!album.isEmpty())q.put("albumIds",new JSONArray().put(album));JSONObject result=new JSONObject(new String(request(s+"/search/metadata","POST",q.toString(),t,6000000),"UTF-8")).getJSONObject("assets");JSONArray items=result.getJSONArray("items");JSONArray unique=new JSONArray();for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);if(seen.add(item.optString("id")))unique.put(item);}slides.addAll(remoteSlides(unique,s,t));if(unique.length()==0)break;String nextCursor=result.isNull("nextCursor")?"":result.optString("nextCursor","");String nextPage=result.isNull("nextPage")?"":result.optString("nextPage","");if(!nextCursor.isEmpty()){cursor=nextCursor;}else if(!nextPage.isEmpty()){cursor="";page=Integer.parseInt(nextPage);}else break;}}ui.post(()->{if(stamp!=revision)return;if(slides.isEmpty()){text("No media found. Choose an album, upload images, or check your login.");return;}if(prefs.getBoolean("gallery.shuffle",false))Collections.shuffle(slides);openFrame(slides,0,true);});});}
 void openFrame(ArrayList<Slide> slides,int index,boolean autoplay){page("Gallery");getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_FULLSCREEN);int flags=View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION;if(Build.VERSION.SDK_INT>=19)flags|=View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY;getWindow().getDecorView().setSystemUiVisibility(flags);frame=new FramePlayer(this,slides,index,autoplay);setContentView(frame);frame.show();}
 void gallerySettings(){page("Gallery settings");EditText duration=input("Seconds per photo (3-3600)",String.valueOf(prefs.getInt("gallery.seconds",10)));EditText timeout=input("Home idle seconds (30-3600)",String.valueOf(prefs.getInt("gallery.idle.seconds",120)));CheckBox auto=new CheckBox(this);auto.setText("Start gallery after inactivity on Home only");auto.setChecked(prefs.getBoolean("gallery.idle",false));body.addView(auto);CheckBox shuffle=new CheckBox(this);shuffle.setText("Shuffle when starting a gallery");shuffle.setChecked(prefs.getBoolean("gallery.shuffle",false));body.addView(shuffle);CheckBox mute=new CheckBox(this);mute.setText("Mute videos");mute.setChecked(prefs.getBoolean("gallery.mute",true));body.addView(mute);CheckBox local=new CheckBox(this);local.setText("Use uploaded photos instead of Immich for idle gallery");local.setChecked(prefs.getBoolean("gallery.local",false));body.addView(local);button("Save gallery settings",()->{try{int seconds=Integer.parseInt(duration.getText().toString()),wait=Integer.parseInt(timeout.getText().toString());if(seconds<3||seconds>3600||wait<30||wait>3600)throw new Exception();prefs.edit().putInt("gallery.seconds",seconds).putInt("gallery.idle.seconds",wait).putBoolean("gallery.idle",auto.isChecked()).putBoolean("gallery.shuffle",shuffle.isChecked()).putBoolean("gallery.mute",mute.isChecked()).putBoolean("gallery.local",local.isChecked()).apply();toast("Saved");}catch(Exception e){toast("Enter photo duration 3-3600 and idle time 30-3600 seconds");}});text("Idle starts only on this app's Home screen. It will not interrupt games, notes or drawing. Not a system-wide Android screensaver. Up to 5,000 remote items per launch; videos cache to disk before playback (256 MiB limit each).");button("Forget saved Immich sign-in",()->forget());}
 @Override public void onBackPressed(){if(frame!=null)home();else super.onBackPressed();}
 @Override protected void onPause(){idle.removeCallbacksAndMessages(null);if(frame!=null)frame.pause();super.onPause();}
 @Override protected void onResume(){super.onResume();if(atHome)armIdle();}
 @Override protected void onDestroy(){idle.removeCallbacksAndMessages(null);if(frame!=null)frame.close();super.onDestroy();}
}
